package com.meridiantrust.sentinel.api;
import com.meridiantrust.sentinel.domain.Domain.*; import com.meridiantrust.sentinel.repo.Repositories.*; import com.meridiantrust.sentinel.service.SentinelService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.security.Principal; import java.util.*;
@RestController @RequestMapping("/api/v1") public class ApiController { final SentinelService service; final Rules rules; final Fx fx; final Customers customers; final Accounts accounts; public ApiController(SentinelService s,Rules r,Fx f,Customers c,Accounts a){service=s;rules=r;fx=f;customers=c;accounts=a;}
 @PostMapping("/customers") @ResponseStatus(HttpStatus.CREATED) Customer customer(@Valid @RequestBody Dto.CustomerIn x){return service.customer(x);} @PostMapping("/accounts") @ResponseStatus(HttpStatus.CREATED) Account account(@Valid @RequestBody Dto.AccountIn x){return service.account(x);} @PostMapping("/transactions") @ResponseStatus(HttpStatus.ACCEPTED) Tx tx(@Valid @RequestBody Dto.TxIn x){return service.transaction(x);}
 @GetMapping("/alerts") List<Map<String,Object>> alerts(){return service.queue().stream().map(a->Map.<String,Object>of("id",a.id,"rule",a.ruleCode,"riskScore",a.riskScore,"status",a.status,"maskedCustomer",mask(a.account.customer.fullName),"account",maskAccount(a.account.accountNumber),"explanation",a.explanation,"evidence",a.evidence,"createdAt",a.createdAt)).toList();}
 @GetMapping("/alerts/{id}") Alert alert(@PathVariable Long id){return service.queue().stream().filter(a->a.id.equals(id)).findFirst().orElseThrow(()->new NoSuchElementException("alert not found"));} @PatchMapping("/alerts/{id}/disposition") Alert disposition(@PathVariable Long id,@Valid @RequestBody Dto.DispositionIn x,Principal p){return service.disposition(id,x,p.getName());} @PostMapping("/alerts/{id}/cases") @ResponseStatus(HttpStatus.CREATED) Case createCase(@PathVariable Long id,Principal p){return service.createCase(id,p.getName());}
 @GetMapping("/rules") List<RuleConfig> rules(){return rules.findAll();} @PutMapping("/rules/{code}") RuleConfig rule(@PathVariable String code,@Valid @RequestBody Dto.RuleIn x){RuleConfig r=rules.findById(code).orElseThrow(()->new NoSuchElementException("rule not found"));r.enabled=x.enabled();r.threshold=x.threshold();r.windowHours=x.windowHours();r.score=x.score();return rules.save(r);} @GetMapping("/fx-rates") List<FxRate> fx(){return fx.findAll();}
 private String mask(String s){return s==null?"":s.substring(0,1)+"***";} private String maskAccount(String s){return "****"+s.substring(Math.max(0,s.length()-4));} }
